mapper.select:
    SELECT action_code,target_id,outcome,actor_type,actor_id,reason,error_code,
       correlation_id,causation_id FROM audit_record
WHERE tenant_id=#{tenantId} AND audit_id=#{auditId}

mapper.update:
    UPDATE workflow_start_link SET status='REQUESTED',
    lock_version=lock_version+1,updated_at=#{now},
    updated_by_type='USER',updated_by_id=#{actorId}
WHERE tenant_id=#{tenantId} AND ticket_id=#{ticketId} AND status='RECOVERY_REQUIRED' AND lock_version=#{linkLockVersion}

    UPDATE message_recovery SET state='REPLAYING',next_attempt_at=#{replayLeaseUntil},
    replay_count=replay_count+1,last_replayed_at=#{now},last_replayed_by_type='USER',
    last_replayed_by_id=#{actorId},last_replay_reason=#{reason},last_replay_correlation_id=#{attemptCorrelation},
    lock_version=lock_version+1,updated_at=#{now2},updated_by_type='USER',updated_by_id=#{actorId2}
WHERE tenant_id=#{tenantId} AND recovery_id=#{recoveryId} AND direction=#{direction} AND source_record_id=#{sourceRecordId}
  AND state='OPEN' AND lock_version=#{lockVersion}
